                <article class="kanban-task" data-task-id="<?php echo $e($task['id']); ?>" draggable="<?php echo $edit?'true':'false'; ?>">
                    <div class="kanban-task__header"><h4><?php echo $e($task['title']); ?></h4><button class="button chisimba-button-secondary" type="button" data-task-toggle aria-expanded="true" aria-controls="task-body-<?php echo $e($task['id']); ?>" aria-label="<?php echo $e('Collapse task: '.$task['title']); ?>">Collapse</button></div>
                    <div class="kanban-task__body" id="task-body-<?php echo $e($task['id']); ?>"><?php if($task['description']!==''): ?><p><?php echo nl2br($e($task['description'])); ?></p><?php endif; ?>
                    <?php if($task['notes']!==''): ?><details><summary>Notes</summary><p><?php echo nl2br($e($task['notes'])); ?></p></details><?php endif; ?>
                    <?php if($task['subtasks']||$edit): ?><div class="kanban-subtasks"><strong>Subtasks</strong><?php foreach($task['subtasks'] as $sub): ?><label class="kanban-subtask"><input type="checkbox" data-subtask-id="<?php echo $e($sub['id']); ?>" <?php echo !empty($sub['iscompleted'])?'checked':''; ?> <?php echo $edit?'':'disabled'; ?>/><span><?php echo $e($sub['title']); ?></span></label><?php endforeach; ?><?php if($edit): ?><form method="post" action="<?php echo $e($url(array('action'=>'savesubtask'))); ?>"><?php echo $hidden($board['id']); ?><input type="hidden" name="taskid" value="<?php echo $e($task['id']); ?>"/><div class="chisimba-cluster kanban-compact-actions"><input name="title" aria-label="New subtask" required/><button class="button chisimba-button-secondary" type="submit">Add</button></div></form><?php endif; ?></div><?php endif; ?>
                    <?php if($edit): ?><div class="chisimba-cluster kanban-task__actions kanban-compact-actions"><?php $statusKeys=array_keys($labels);$statusIndex=array_search($status,$statusKeys,true);foreach(array('left'=>$statusIndex-1,'right'=>$statusIndex+1) as $direction=>$targetIndex):if(isset($statusKeys[$targetIndex])): ?><form method="post" action="<?php echo $e($url(array('action'=>'movetask'))); ?>" data-task-move><?php echo $hidden($board['id']); ?><input type="hidden" name="taskid" value="<?php echo $e($task['id']); ?>"/><input type="hidden" name="status" value="<?php echo $e($statusKeys[$targetIndex]); ?>"/><input type="hidden" name="sortorder" value="<?php echo time(); ?>"/><button class="button chisimba-button-secondary" type="submit">Move <?php echo $e($direction); ?></button></form><?php endif;endforeach; ?><details><summary class="button chisimba-button-secondary">Edit</summary><form class="chisimba-form kanban-popover" method="post" action="<?php echo $e($url(array('action'=>'savetask'))); ?>"><?php echo $hidden($board['id']); ?><input type="hidden" name="taskid" value="<?php echo $e($task['id']); ?>"/><div class="chisimba-form-field"><label>Title<input name="title" value="<?php echo $e($task['title']); ?>" required/></label></div><div class="chisimba-form-field"><label>Description<textarea name="description"><?php echo $e($task['description']); ?></textarea></label></div><div class="chisimba-form-field"><label>Notes<textarea name="notes"><?php echo $e($task['notes']); ?></textarea></label></div><button class="button" type="submit">Save</button></form></details><form method="post" action="<?php echo $e($url(array('action'=>'deletetask'))); ?>" data-confirm="Delete this task?"><?php echo $hidden($board['id']); ?><input type="hidden" name="taskid" value="<?php echo $e($task['id']); ?>"/><button class="button chisimba-button-danger" type="submit">Delete</button></form></div><?php endif; ?>
                    </div>
                </article>
